local_probe.script:
import {makeLocalFixtureSignature,nonceOf,verifyNep413SignedMessage} from './packages/wallet-adapter/src/nep413.mjs';
import {makeChallenge,verifyChallengeProof} from './packages/wallet-adapter/src/verify-binding.mjs';
const nonce=nonceOf('codex-domain-review-2'), message='fixture', domain='showstake.example';
const s=makeLocalFixtureSignature({message,nonce,recipient:domain});
const mislabeled=verifyNep413SignedMessage({message,nonce,recipient:domain,accountId:s.accountId,publicKey:s.publicKey.replace('ed25519:','secp256k1:'),signature:s.signature});
const challenge=makeChallenge({purpose:'login',domain,network:'testnet',accountId:s.accountId,nonce,message});
const proof={accountId:s.accountId,publicKey:s.publicKey,signature:s.signature};
const omittedExpectations=verifyChallengeProof({challenge,proof,consumedNonces:new Set()});
console.log(JSON.stringify({mislabeledKeyType:mislabeled,missingExpectedDomainNetwork:omittedExpectations}));
process.exitCode=(mislabeled.ok||omittedExpectations.ok)?1:0;
